:root {
  color-scheme: dark;
  --stage-size: min(72vw, 72vh, 640px);
  --panel-bg: rgba(20, 22, 29, 0.86);
  --panel-border: rgba(255, 255, 255, 0.12);
  --text: #f6f1e8;
  --muted: #b8b3aa;
  --gold: #fec901;
  --ember: #fe6a28;
}

* {
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  margin: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 26% 22%, rgba(74, 97, 109, 0.3), transparent 32%),
    linear-gradient(135deg, #121319 0%, #22222b 52%, #15161c 100%);
