}

button,
select {
  font: inherit;
}

.animation-page {
  position: relative;
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 84px 24px 36px;
}

.toolbar {
  position: fixed;
  top: 16px;
  right: 16px;
  z-index: 30;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  max-width: min(760px, calc(100vw - 32px));
  padding: 10px;
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  background: var(--panel-bg);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(14px);
}

.control-group {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 34px;
}

.control-label {
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
}

.toolbar button,
.toolbar select {
  min-height: 34px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
  outline: none;
}

.toolbar button {
  display: inline-grid;
  place-items: center;
  padding: 0 12px;
  cursor: pointer;
  transition: background 140ms ease, border-color 140ms ease, transform 140ms ease;
}

.toolbar button:hover,
.toolbar select:hover {
  border-color: rgba(254, 201, 1, 0.55);
  background: rgba(254, 201, 1, 0.14);
}

.toolbar button:active {
  transform: translateY(1px);
}

.toolbar button.is-active {
  border-color: rgba(127, 219, 254, 0.8);
  background: rgba(127, 219, 254, 0.18);
}

.toolbar select {
  padding: 0 28px 0 10px;
  color: var(--text);
  cursor: pointer;
}

.toolbar option {
  color: #15161c;
}

.stage {
  position: relative;
  width: var(--stage-size);
  max-width: calc(100vw - 48px);
  aspect-ratio: 1;
}

.owl-wrap {
  position: absolute;
