          setTimeoutTracked(startHeadRotatingLoop, 1200);
        }
        return;
      }
      const direction = Math.random() > 0.5 ? 1 : -1;
      const angle = direction * random(4, 10);
      const y = random(-4, 4);
      app.els.headGroup.style.transition = "transform 250ms ease, filter 250ms ease";
      app.els.headGroup.style.transform = `rotate(${angle}deg) translate(${direction * 6}px, ${y}px)`;
      app.els.headGroup.style.filter = "blur(2px)";
      setTimeoutTracked(() => {
        app.els.headGroup.style.filter = "blur(0)";
      }, 250);
      setTimeoutTracked(step, 1250);
    }

    step();
  }

  function startMarkingTime() {
    app.state.headLocked = true;
    app.els.stage.classList.remove("mode-head-shake", "mode-stabilized");
    app.els.headGroup.style.transform = "";
    app.els.stage.classList.add("marking-time");
    setTimeoutTracked(() => {
      app.els.stage.classList.remove("marking-time");
      app.state.headLocked = false;
    }, 6000);
  }

  function startNoteSmoke() {
    emitNote();
    setIntervalTracked(emitNote, 820);
  }

  function emitNote() {
    const note = document.createElement("div");
    note.className = "note";
    note.textContent = pick(["\\u266A", "\\u266B", "\\u2669"]);
    note.style.left = `${random(43, 58)}%`;
    note.style.setProperty("--note-drift", `${random(-34, 34)}px`);
    app.els.particleLayer.appendChild(note);
    setTimeoutTracked(() => note.remove(), 2500);
  }

  async function startThinking() {
    if (app.state.thinking) {
      return;
    }
    stopPassiveAnimations({ keepBlink: true, keepWand: false, keepRightWing: false });
    app.state.mode = "thinking";
    app.state.thinking = true;
    app.state.error = false;
    app.els.thinkingToggle.classList.add("is-active");
    app.els.thinkingToggle.textContent = "End thinking";
    setIndicator("thinking", true);
    startEyeThinking();
    rightWingLift();
    await wait(500);
    if (app.state.thinking) {
      startRightWingTremor();
    }
  }

  async function endThinking() {
    if (!app.state.thinking) {
      return;
    }
    app.state.thinking = false;
    app.els.thinkingToggle.classList.remove("is-active");
    app.els.thinkingToggle.textContent = "Start thinking";
    setIndicator("thinking", false);
    stopBlink();
    resetEyes(true);
    setIndicator("answer", true);
    rightWingBack();
    await wait(250);
    if (app.els.answerIndicator) {
      app.els.answerIndicator.style.opacity = "1";
    }
    await wait(520);
    setIndicator("answer", false);
    startBlink();
    startStandby(app.state.standbyChoice || "random");
  }

  function rightWingLift() {
    app.els.stage.classList.remove("right-wing-ready", "right-wing-tremor");
    app.els.stage.classList.add("right-wing-lifting");
    setTimeoutTracked(() => {
      app.els.stage.classList.remove("right-wing-lifting");
      app.els.stage.classList.add("right-wing-lifted", "right-wing-ready");
      nudgeRightWingPaths(1);
    }, 500);
  }

  function startRightWingTremor() {
    app.els.stage.classList.add("right-wing-tremor");
  }

  async function rightWingBack() {
    app.els.stage.classList.remove("right-wing-tremor");
    await wait(250);
    app.els.stage.classList.remove("right-wing-lifted");
    app.els.stage.classList.add("right-wing-ready");
    nudgeRightWingPaths(0);
    setTimeoutTracked(() => {
      resetRightWing();
    }, 500);
  }

  function nudgeRightWingPaths(amount) {
    const offsets = {
      right_wing_bg: [amount * 2, amount * -1],
      right_wing_3_and_4: [amount * 5, amount * -4],
      right_wing_separator_34: [amount * 7, amount * -5],
      right_wing_2: [amount * 4, amount * -3],
      right_wing_separator_23: [amount * 4, amount * -4],
      right_wing_1: [amount * 3, amount * -6],
      right_wing_separator_12: [amount * 4, amount * -5]
    };
    rightWingIds.forEach((id) => {
      const el = $("#" + id);
      if (!el || !el.dataset.originalD) {
        return;
      }
      const offset = offsets[id] || [0, 0];
      el.style.transition = "d 500ms ease, transform 500ms ease";
      el.style.transform = `translate(${offset[0]}px, ${offset[1]}px)`;
    });
  }

  async function triggerError() {
    app.state.error = true;
    app.state.mode = "error";
    stopPassiveAnimations({ keepBlink: false });
    stopBlink();
    setIndicator("error", true);
    eyeSurprise();
    await wait(5600);
    if (!app.state.error || app.state.mode !== "error") {
      return;
    }
    setIndicator("error", false);
    app.state.error = false;
    startStandby(app.state.standbyChoice || "random");
  }

  async function showWand() {
    if (app.state.wand === "showing" || app.state.wand === "ready" || app.state.wand === "tremor") {
      refreshWandRetractionTimer();
      return;
    }
    if (app.state.error || app.state.thinking) {
      return;
    }

    app.state.wand = "showing";
    app.els.wandLayer.classList.remove("is-retracting");
    app.els.stage.classList.add("left-wing-clench");
    refreshWandRetractionTimer();
    await wait(100);
    if (app.state.wand !== "showing") {
      return;
    }
    burstAtWand(16);
    app.els.wandLayer.classList.add("is-visible", "is-materializing");
    await wait(150);
    if (app.state.wand !== "showing") {
      return;
    }
    app.els.wandLayer.classList.remove("is-materializing");
    app.els.wandLayer.classList.add("is-ready");
    app.els.stage.classList.remove("left-wing-clench");
    app.els.stage.classList.add("left-wing-wand-ready");
    await wait(150);
    if (app.state.wand !== "showing") {
      return;
    }
    app.state.wand = "ready";
    maybeStartWandTremor();
  }

  function maybeStartWandTremor() {
    if (Date.now() < app.state.wandSuppressUntil || app.state.wand !== "ready") {
      return;
    }
    app.state.wand = "tremor";
    app.els.stage.classList.add("wand-tremor-active");
    app.els.wandLayer.classList.add("is-tremoring");
  }

  async function stopWandTremor(resetMs) {
    if (app.state.wand === "tremor") {
      app.state.wand = "ready";
    }
    app.els.stage.classList.remove("wand-tremor-active");
    app.els.wandLayer.classList.remove("is-tremoring");
    if (resetMs) {
      await wait(resetMs);
    }
  }

  function refreshWandRetractionTimer() {
    clearTimer(app.state.retractionTimer);
    app.state.retractionTimer = setTimeoutTracked(() => {
      retractWand();
    }, 30000);
  }

  async function retractWand() {
    if (app.state.wand === "hidden" || app.state.wand === "showing" || app.state.wand === "using") {
      return;
    }
    app.state.wand = "retracting";
    await stopWandTremor(100);
    if (app.state.wand !== "retracting") {
      return;
    }
    app.els.wandLayer.classList.add("is-retracting");
    app.els.stage.classList.remove("left-wing-wand-ready");
    await wait(400);
    if (app.state.wand === "retracting") {
      resetWand();
    }
  }

  async function useMagic(target) {
    if (app.state.error) {
      app.state.error = false;
      app.state.mode = "magic";
      setIndicator("error", false);
      resetEyes(true);
      startBlink();
    }
    if (app.state.thinking) {
      await endThinking();
    }
    if (app.state.wand === "hidden" || app.state.wand === "retracting") {
      resetWand();
      await showWand();
    }
    if (app.state.wand === "showing") {
      await wait(420);
    }
    if (app.state.wand === "tremor") {
      await stopWandTremor(100);
    } else {
      await wait(100);
    }
    if (app.state.wand === "hidden") {
      return;
    }
    app.state.wand = "using";
    app.state.wandSuppressUntil = Date.now() + 10000;
    clearProjectiles();
    fireMagicAt(target);
    refreshWandRetractionTimer();
    app.state.wand = "ready";
    setTimeoutTracked(() => {
      if (app.state.wand === "ready") {
        maybeStartWandTremor();
      }
    }, 10000);
  }

  function centerOf(el) {
    const rect = el.getBoundingClientRect();
    const stageRect = app.els.stage.getBoundingClientRect();
    return {
      x: rect.left + rect.width / 2 - stageRect.left,
      y: rect.top + rect.height / 2 - stageRect.top
    };
  }

  function fireMagicAt(target) {
    const middle = $("#middle_filler", app.els.wandSvg) || app.els.wandLayer;
    const start = centerOf(middle);
    const end = centerOf(target.closest(".magic-target") || target);
    const control = {
      x: (start.x + end.x) / 2 + random(-80, 80),
      y: Math.min(start.y, end.y) - random(80, 140)
    };
    const started = performance.now();
    burst(start.x, start.y, 12);

    function frame(time) {
      const t = clamp((time - started) / 400, 0, 1);
      const point = quadratic(start, control, end, easeOutCubic(t));
      const tangent = quadratic(start, control, end, clamp(easeOutCubic(t) + 0.02, 0, 1));
      addTrail(point, tangent, t);
      if (t < 1) {
        requestFrame(frame);
      } else {
        burst(end.x, end.y, 18);
      }
    }

    requestFrame(frame);
  }

  function quadratic(a, b, c, t) {
    const mt = 1 - t;
    return {
      x: mt * mt * a.x + 2 * mt * t * b.x + t * t * c.x,
      y: mt * mt * a.y + 2 * mt * t * b.y + t * t * c.y
    };
  }

  function easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  function addTrail(point, next, t) {
    const node = document.createElement("div");
    node.className = t > 0.86 ? "star-particle" : "trail-particle";
    const angle = Math.atan2(next.y - point.y, next.x - point.x);
    node.style.transform = `translate(${point.x}px, ${point.y}px) translate(-50%, -50%) rotate(${angle}rad) scale(${random(0.72, 1.18)})`;
    node.style.opacity = String(1 - t * 0.35);
    node.style.setProperty("--trail-w", `${random(18, 34)}px`);
    node.style.setProperty("--trail-h", `${random(6, 11)}px`);
    app.els.particleLayer.appendChild(node);
    app.state.projectileNodes.add(node);
    setTimeoutTracked(() => {
      node.remove();
      app.state.projectileNodes.delete(node);
    }, 360);
  }

  function burstAtWand(count) {
    const center = centerOf(app.els.wandLayer);
    burst(center.x, center.y, count);
  }

  function burst(x, y, count) {
    for (let i = 0; i < count; i += 1) {
      const node = document.createElement("div");
      node.className = "burst-particle";
      node.style.transform = `translate(${x}px, ${y}px)`;
      node.style.setProperty("--burst-x", `${random(-54, 54)}px`);
      node.style.setProperty("--burst-y", `${random(-54, 54)}px`);
      node.style.animationDelay = `${random(0, 60)}ms`;
      app.els.particleLayer.appendChild(node);
      app.state.projectileNodes.add(node);
      setTimeoutTracked(() => {
        node.remove();
        app.state.projectileNodes.delete(node);
      }, 660);
    }
  }

  function clearProjectiles() {
    app.state.projectileNodes.forEach((node) => node.remove());
    app.state.projectileNodes.clear();
  }

  window.owlAnimationSandbox = {
    startStandby,
    startThinking,
    endThinking,
    triggerError,
    showWand,
    useMagic,
    startEyeChase,
    resetEyes
  };

  document.addEventListener("DOMContentLoaded", init);
})();

